import json

class CookiesUtil:
    def __init__(self, cookies_file):
        self._cookies_file = cookies_file
        self._cookies = None

    def get_cookies(self, response):
        self._cookies = response['cookies']
        self._save_cookies()

    def load_cookies(self):
        try:
            with open(self._cookies_file, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return {}

    def _save_cookies(self):
        try:
            with open(self._cookies_file, 'w') as file:
                json.dump(self._cookies, file)
            return True
        except OSError:
            return False

    def set_cookies(self, request):
        request['cookies'] = self._get_cookie_string()

    def _get_cookie_string(self):
        return '; '.join(f'{key}={value}' for key, value in self._cookies.items())

    @property
    def cookies_file(self):
        return self._cookies_file

    @cookies_file.setter
    def cookies_file(self, value):
        self._cookies_file = value

    @property
    def cookies(self):
        return self._cookies

    @cookies.setter
    def cookies(self, value):
        self._cookies = value
